import itertools, json
jobs='ABCDE'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
trans=dict(zip(jobs,[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]))
def nominal(r):
 return sum(slot[j][i] for i,j in enumerate(r))+sum(trans[a][jobs.index(b)] for a,b in zip(r,r[1:]))
def incident(r,k):
 pos={j:r.index(j)+1 for j in jobs}
 if pos['A']>pos['D']: return None
 if k=='rain':
  if pos['C']==5 or pos['A']==1: return None
  return nominal(r)+8*max(0,pos['E']-1)
 if k=='road':
  if pos['B']==1 or pos['C']==2: return None
  return nominal(r)+5*max(0,pos['D']-3)
 if pos['D']==5 or pos['B']==5: return None
 return nominal(r)+5*max(0,pos['E']-2)
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'): continue
 neighbors=[(p,0)]
 for i in range(5):
  for j in range(i+1,5):
   q=list(p); q[i],q[j]=q[j],q[i]
   neighbors.append((tuple(q),1))
 best={}
 for k in ['rain','road','lift']:
  choices=[(c+ex,''.join(q)) for q,ex in neighbors if (c:=incident(q,k)) is not None]
  if not choices: break
  best[k]=min(choices)
 if len(best)==3: results.append((nominal(p)+max(c for c,r in best.values()),''.join(p),best))
results.sort()
score,p,best=results[0]
print(json.dumps({'roster':p,'score':score,'repairs':{k:r for k,(c,r) in best.items()},'repair_costs':{k:c for k,(c,r) in best.items()},'feasible_count':len(results),'next_score':min(s for s,p,b in results if s>score)}))
print('optimal publications:', [(s,p) for s,p,b in results if s==score])
print('published nominal:',nominal(tuple(p)))

