import itertools,json
jobs='ABCDE'; published='EABDC'
slot={'A':[10,7,11,4,4],'B':[3,1,1,4,8],'C':[5,4,5,6,2],'D':[3,3,7,1,11],'E':[10,9,10,1,9]}
t=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
def distance(r):
 p=[published.index(j) for j in r]; seen=set(); cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1; j=i
   while j not in seen:
    seen.add(j); j=p[j]
 return 5-cycles
classes={i:[] for i in range(3)}
for r in itertools.permutations(jobs):
 d=distance(r)
 if d>2 or r.index('A')>r.index('D') or r[4]=='C' or r[0] in 'AE': continue
 nominal=sum(slot[j][i] for i,j in enumerate(r))+sum(t[jobs.index(a)][jobs.index(b)] for a,b in zip(r,r[1:]))
 cost=nominal+8*r.index('E')+d+(10 if d==2 else 0)
 classes[d].append((cost,''.join(r)))
best=min(x for c in classes.values() for x in c)
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(c)[0] if c else None for d,c in classes.items()},'feasible_by_swaps':{str(d):len(c) for d,c in classes.items()}}))
print({d:sorted(c) for d,c in classes.items()})

